function fe = ElementRHS4ConPen(nnpe,nqptv,wtq,bigN,detj,data)%% called by MechMet, MechMonics and QuadPoints2NodalPoints_FEpX%% forms elemental RHS  matrix for consistent penalty procedure for% determining nodal point values using quad point information%fe= zeros(nnpe,1);feqp= zeros(nnpe,1);bigNqp = zeros(nnpe,1);  for j=1:1:nqptv  	  xkfac=wtq(j)*detj(j);  bigNqp(:) = bigN(:,j);  feqp = xkfac*(bigNqp*data(j));  fe = fe + feqp;end